<?php
require_once __DIR__ . '/config.php';
$user=current_user(); if(!$user) redirect('login.php');
$stmt=$pdo->prepare('SELECT * FROM users WHERE id=?'); $stmt->execute([$user['id']]); $profile=$stmt->fetch();
$stmt=$pdo->prepare("SELECT * FROM orders WHERE user_id=? AND status='open' ORDER BY id DESC"); $stmt->execute([$user['id']]); $open=$stmt->fetchAll();
$stmt=$pdo->prepare("SELECT * FROM orders WHERE user_id=? AND status='closed' ORDER BY id DESC"); $stmt->execute([$user['id']]); $closed=$stmt->fetchAll(); site_header('Профиль — COMFY');
?>
<main class="container"><section class="profile-meta"><h1><?= e($profile['name']) ?></h1><p><?= e($profile['email']) ?> &nbsp; <?= e($profile['phone']) ?></p><p><?= e($profile['address']) ?></p></section><?php if(!empty($_SESSION['flash'])): ?><p class="flash"><?= e($_SESSION['flash']); unset($_SESSION['flash']); ?></p><?php endif; ?><h2 class="section-title">Список заказов пользователя</h2><h2 class="center">Открытые заказы</h2><?php foreach($open as $o): ?><article class="profile-order"><div><h3>Наименование: <?= e($o['customer_name']) ?></h3><p>Дата заказа: <i><?= e(date('j F, Y', strtotime($o['order_date']))) ?></i> Дата доставки: <i><?= e(date('j F, Y', strtotime($o['delivery_date']))) ?></i></p></div><form action="controllers/action_add_product.php" method="post"><input type="hidden" name="action" value="cancel_order"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><button class="btn-dark">Отменить</button></form></article><?php endforeach; ?><section class="closed-orders"><h2 class="center">Закрытые заказы</h2><?php foreach($closed as $o): ?><article><h3>Номер заказа: <?= e($o['order_number']) ?></h3><p>Дата заказа: <i><?= e(date('j F, Y', strtotime($o['order_date']))) ?></i> Дата доставки: <i><?= e(date('j F, Y', strtotime($o['delivery_date']))) ?></i></p></article><?php endforeach; ?></section></main><?php site_footer(); ?>
